// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(65000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/product/66VCHSJNUP`);
    const unitPrice = Number((await page.locator(".product-title-row .product-price").innerText()).replace(/[^0-9.]/g, ""));
    await page.getByLabel("Qty:").selectOption("10");
    await page.getByRole("button", { name: "Add to Bag" }).click();
    await expect(page.getByTestId("cart-heading")).toContainText("Cart (10)");
    await expect(page.getByText("Quantity:")).toContainText("Quantity: 10");
    await expect(page.locator(".cart-summary-item-row strong")).toContainText(`$${(unitPrice * 10).toFixed(2)}`);
});
